  it('lets money received against a cancelled invoice pay the client’s other invoices, then stand as a credit', () => {
    const db = practice()
    const cancelled = createWork(db, partner, WORK.payments, { client_ref: 'C1', amount_pence: 10000, invoice_date: local(-40), due_date: local(-10) })
    createWork(db, partner, WORK.payments, { client_ref: 'C1', amount_pence: 3000, invoice_date: local(-5), due_date: local(9) })
    addReceipt(db, partner, { client_ref: 'C1', amount_pence: 8000, payment_id: cancelled.id })
    expect(clientReceivables(db, partner, 'C1')).toMatchObject({ outstanding_pence: 2000, credit_pence: 0 })
    updateWork(db, partner, WORK.payments, cancelled.id, { status: 'cancelled' })
    expect(clientReceivables(db, partner, 'C1')).toMatchObject({ outstanding_pence: 0, credit_pence: 5000 })
  })
})
